select 'engineering', 'Khatib & Alami', 'Khatib & Alami', 'دبي', 'تيكوم', '+971 4 425 2222', 'https://www.khatibalami.com', null, 'استشارات هندسية ومعمارية تشمل التصميم والتخطيط العمراني والنقل والطاقة والمياه والبيئة والخدمات الرقمية.', 'https://www.khatibalami.com/contact-us/', 'شركة استشارات هندسية ومعمارية دولية تقدم التصميم المستدام والخدمات الرقمية وحلول البنية التحتية، بخبرة تزيد على 60 عامًا حسب موقعها. تشمل تخصصاتها العمارة والتصميم الداخلي والتخطيط العمراني والنقل والطاقة والمياه والبيئة.', null, 'dubai@khatibalami.com', 'برج آي رايز، تيكوم، الطابق 22، مكتب E1 وE2-22، دبي', null, array['مساكن بولغري أوشن في جزيرة خليج جميرا بدبي', 'وجهة سفن الترفيهية في أبها بالسعودية', 'جسر الجادرية في بغداد', 'طريق الفحيحيل السريع (طريق 30) في الكويت']::text[], 'تضم الشركة أكثر من 6,500 موظف في أكثر من 30 مكتبًا حول العالم، وأنجزت 5,500 مشروع حسب موقعها.', true
where not exists (select 1 from public.service_providers where category = 'engineering' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Khatib & Alami'));
