select 'engineering', 'Dar Al-Handasah', 'Dar Al-Handasah', 'دبي', 'مركز دبي المالي العالمي', '+971 4 306 0000', 'https://www.dar.com', null, 'استشارات في التصميم والتخطيط والهندسة وإدارة المشاريع للمباني والبنية التحتية والنقل والمياه.', 'https://www.dar.com/contact/region/middle-east', 'شركة استشارات تقدم التصميم والتخطيط والهندسة واستشارات الاستدامة وإدارة المشاريع للمباني والمدن والنقل والبنية التحتية والمياه والبيئة. وهي العضو المؤسس لمجموعة سدارة، ولها أربعة مكاتب في الإمارات.', null, null, 'مكتب 2401، برج إندكس، مركز دبي المالي العالمي، ص.ب 506855، دبي', null, array['مبنيان في خور الراحة بأبوظبي', 'الكونكورس C في مطار دبي الدولي']::text[], 'يضم أكثر من 10,700 متخصص في مكاتب حول العالم، ومؤسسه كمال الشاعر حسب موقع الشركة.', true
where not exists (select 1 from public.service_providers where category = 'engineering' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Dar Al-Handasah'));
