select 'engineering', 'Engineering Consultants Group (ECG)', 'Engineering Consultants Group (ECG)', 'العين', null, '+971 3 737 7015', 'https://www.ecgsa.com', 1969, 'دراسات وتصميم هندسي ومعماري وإدارة إنشاءات وإشراف وإدارة مشاريع للمباني والنقل والمرافق والتطوير العمراني.', 'https://www.ecgsa.com/contact-us/', 'مجموعة استشارات هندسية تأسست عام 1969 على يد محمود سامي عبدالقوي وأشرف حسن علوبة، وتقدم الدراسات والتصميم الهندسي والمعماري وإدارة الإنشاءات والإشراف وإدارة المشاريع. افتتحت فرعها في أبوظبي بين عامي 1983 و1991، وأصبحت مملوكة بالكامل لشركة Dorsch Global في 2025.', 'https://www.ecgsa.com/wp-content/uploads/2022/09/logowh.png', 'ecg@ecgsa.com', 'مكتب رقم 2، مبنى علي عزيز مكتوم، شارع زايد بن سلطان، ص.ب 29556، العين', null, array['تطوير الجانب البري لمبنى المسافرين بمطار أبوظبي الدولي (ميدفيلد)', 'مخيمات قصحويرة وشاه لجهاز حماية المنشآت الحيوية (CICPA)', 'مشروع الغدير - المرحلة الأولى', 'تحويل المستودع رقم 1 في ميناء زايد إلى مكاتب', 'أربعة مبانٍ تجارية في مطار أبوظبي الدولي']::text[], 'أسسها محمود سامي عبدالقوي وأشرف حسن علوبة كشراكة عام 1969.', true
where not exists (select 1 from public.service_providers where category = 'engineering' and emirate = 'العين' and lower(coalesce(name_en, name_ar)) = lower('Engineering Consultants Group (ECG)'));
