select 'interior', 'Spazio Interior Decoration LLC', 'Spazio Interior Decoration LLC', 'دبي', 'البرشاء 1', '+971 4 399 0011', 'https://spazio.ae', 2008, 'تصميم داخلي وتنفيذ تشطيبات متكاملة للمشاريع السكنية والتجارية والفندقية مع تصنيع النجارة والأثاث داخليًا.', 'https://spazio.ae/about-us/', 'تأسست سبيتسيو للديكور الداخلي في دبي عام 2008، وتعمل بنموذج التصميم والتنفيذ. لديها مرافق تصنيع للنجارة والألمنيوم والأثاث المخصص، ومكاتب في عدة دول.', null, 'info@spazio.ae', 'مكتب 2703، برج API Trio، البرشاء 1، دبي', null, array['تشطيب مكاتب تجارية في دبي', 'صالة عرض أثاث HENGE', 'مقر شركة NEWEAST', 'تصميم داخلي لقصر في دبي', 'فندق Two Seasons']::text[], 'يضم فريقها أكثر من 150 موظفًا داخليًا.', true
where not exists (select 1 from public.service_providers where category = 'interior' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Spazio Interior Decoration LLC'));
