select 'legal', 'Al Tamimi & Company', 'Al Tamimi & Company', 'دبي', 'مركز دبي المالي العالمي', '+971 4 364 1641', 'https://www.tamimi.com', 1989, 'مكتب محاماة لديه ممارسة متخصصة في العقارات وقطاع العقارات والإنشاءات ضمن خدماته القانونية.', 'https://www.tamimi.com/offices/uae/dubai/', 'مكتب محاماة إقليمي افتتح أول مكاتبه في الإمارات بالشارقة عام 1989، ورئيسه في مركز دبي المالي العالمي. لديه ممارسة للعقارات وقطاع للعقارات والإنشاءات، ويعمل عبر 17 مكتبًا في 9 دول.', 'https://www.tamimi.com/wp-content/themes/tamimi-2020-new-design/assets/img/brands/al-tamimi.svg?=v5', 'info@tamimi.com', 'أبراج سنترال بارك، الطابق 7، شارع العملات، مركز دبي المالي العالمي، دبي', 'https://goo.gl/maps/PpU9wCKMYmpfYge79', '{}'::text[], 'يضم المكتب 360 محاميًا في 17 مكتبًا عبر 9 دول بحسب موقعه.', true
where not exists (select 1 from public.service_providers where category = 'legal' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Al Tamimi & Company'));
