select 'residency', 'Shuraa Management and Consultancy LLC', 'Shuraa Management and Consultancy LLC', 'دبي', 'شارع الشيخ زايد', '+971 4 408 1900', 'https://www.shuraa.com', 2001, 'تأسيس الشركات في البر الرئيسي والمناطق الحرة والأوفشور، وتراخيص الأعمال، وخدمات PRO والتأشيرة الذهبية.', 'https://www.shuraa.com/contact-us/', 'تعمل الشركة تحت علامة Shuraa Business Setup وتذكر أنها تقدم استشارات تأسيس الأعمال في دبي منذ عام 2001. لها مكاتب خارج الإمارات في لندن وأمستردام ونيودلهي ومومباي.', 'https://www.shuraa.com/wp-content/uploads/2023/07/Shuraa-Logo-150-x-87px-Original-170x99.png', 'info@shuraa.com', 'الطابق الخامس، برج أسبن التجاري، بالقرب من محطة مترو المركز المالي، شارع الشيخ زايد، دبي', 'https://goo.gl/maps/BKejHhpkZaw5PwsKA', array['تأسيس الشركات في البر الرئيسي والمناطق الحرة والأوفشور', 'التراخيص التجارية والصناعية والمهنية', 'خدمات PRO في دبي وأبوظبي والشارقة وعجمان', 'التأشيرة الذهبية', 'الكفيل المحلي']::text[], null, true
