select 'residency', 'Sovereign Corporate Services (ME) Limited', 'Sovereign Corporate Services (ME) Limited', 'أبوظبي', 'جزيرة الريم', '+971 2 448 5120', 'https://www.sovereigngroup.com', null, 'تأسيس الشركات في سوق أبوظبي العالمي والبر الرئيسي والمناطق الحرة، وخدمات PRO، والإقامة والتأشيرة الذهبية.', 'https://www.sovereigngroup.com/offices/abu-dhabi/', 'مكتب مجموعة Sovereign في أبوظبي ومرخص كمزود خدمات شركات في سوق أبوظبي العالمي. تأسست المجموعة عام 1987 وتعمل في الإمارات منذ أكثر من 20 عاماً، واستحوذت على PRO Partner Group عام 2022.', null, 'ad@SovereignGroup.com', '911 برج أداكس، جزيرة الريم، أبوظبي', null, array['تأسيس الشركات في سوق أبوظبي العالمي والبر الرئيسي والمناطق الحرة', 'خدمات PRO', 'التأشيرة الذهبية وتأشيرات التقاعد والعمل عن بعد', 'الصناديق الائتمانية والمؤسسات', 'المكتب المسجل والسكرتارية']::text[], 'يدير مكتب أبوظبي المدير العام سايمون غوردون، وتذكر المجموعة أن لديها أكثر من 90 متخصصاً في الإمارات.', true
where not exists (select 1 from public.service_providers where category = 'residency' and emirate = 'أبوظبي' and lower(coalesce(name_en, name_ar)) = lower('Sovereign Corporate Services (ME) Limited'));
