select 'car_rental', 'Thrifty Car Rental UAE – Abu Dhabi', 'Thrifty Car Rental UAE – Abu Dhabi', 'أبوظبي', 'مصفح', '+971 2 813 0300', 'https://www.thriftyuae.com', 1989, 'المكتب الرئيسي لثريفتي لتأجير السيارات في أبوظبي بمنطقة مصفح.', 'https://www.thriftyuae.com/contact-us', 'تأسست ثريفتي الإمارات عام 1989 كجزء من مؤسسات عبدالله أحمد الموسى، وتقدم التأجير قصير الأجل للسياح والمقيمين والتأجير طويل الأجل للشركات والأفراد. ولها فروع في أبوظبي ودبي وعجمان والعين والفجيرة ورأس الخيمة والشارقة، وورش في دبي وأبوظبي.', 'https://fcdn.thriftyuae.com/media/images/new-logo.png', null, 'M-14 مصفح، أبوظبي', null, array['تأجير يومي وأسبوعي وشهري', 'تأجير شخصي وتجاري طويل الأجل', 'توصيل واستلام السيارات', 'مساعدة على الطريق على مدار الساعة', 'خدمة تصاريح CICPA لمواقع المشاريع في أبوظبي']::text[], null, true
