select 'car_rental', 'Diamondlease', 'Diamondlease', 'دبي', null, null, 'https://diamondlease.com', 1996, 'شركة لتأجير السيارات والتأجير طويل الأجل تابعة لمجموعة الحبتور، تأسست عام 1996.', 'https://www.habtoor.com/en/12/divisions/vehicle-leasing/', 'تأسست دايموندليس عام 1996 وهي ضمن قطاع تأجير المركبات في مجموعة الحبتور، وتقدم التأجير قصير الأجل والتأجير للشركات ونقل الحافلات للمدارس والفنادق والمكاتب. ولها فروع في دبي ومطار دبي الدولي وأبوظبي، وهي حاصلة على شهادة ISO 9001:2000.', null, null, null, null, array['تأجير السيارات قصير الأجل', 'التأجير طويل الأجل للشركات', 'نقل بالحافلات للمدارس والفنادق والمكاتب', 'سيارات مع سائق', 'سيارات كهربائية ضمن الأسطول']::text[], null, true
