select 'cleaning', 'Elite Maids', 'Elite Maids', 'دبي', 'Jumeirah Village Circle (JVC)', '+97145930048', 'https://elitemaids.ae/', 2013, 'شركة تنظيف في دبي تأسست عام 2013 تقدم تنظيف المنازل بالساعة والتنظيف العميق وتنظيف الانتقال.', 'https://elitemaids.ae/', 'إيليت ميدز شركة تنظيف في دبي تأسست عام 2013، وتذكر أنها توظف عمال النظافة مباشرة وتدربهم وتكفلهم وتؤمّن عليهم. وتقول إنها مرخصة من دائرة الاقتصاد والسياحة في دبي ومؤمنة بالكامل.', null, null, 'مكتب 201B، برايم بزنس سنتر، قرية جميرا الدائرية، دبي', null, array['تنظيف المنازل بالساعة', 'تنظيف عميق', 'تنظيف عند الانتقال والخروج', 'تنظيف الكنب والسجاد والمراتب', 'تنظيف تجاري للمكاتب والمستودعات']::text[], 'يذكر الموقع أن لديها أكثر من 500 موظف، وأن إدارتها تملك عشر سنوات من الخبرة في التنظيف في كندا.', true
where not exists (select 1 from public.service_providers where category = 'cleaning' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Elite Maids'));
