select 'cleaning', 'Maid Corner', 'Maid Corner', 'دبي', 'Al Barsha 1', '+971585789800', 'https://maidcorner.com/', 2018, 'وكالة في دبي تقدم خادمات بدوام جزئي وبالساعة وتنظيفاً عميقاً وتنظيف الانتقال.', 'https://maidcorner.com/', 'تأسست ميد كورنر عام 2018 لتقديم خدمات التدبير المنزلي لسكان دبي عبر نموذج الوكالة بدلاً من كفالة الخادمة. وتعتمد فريقاً من الفلبينيات يخضعن للتحقق من الخلفية والتدريب قبل أول حجز، بأسعار شاملة الضريبة.', 'https://maidcorner.com/wp-content/uploads/2023/12/Maid-Corner-Logo-2.svg', 'booking@maidcorner.com', 'مكتب 4441، بناية بيناكل، شارع الشيخ زايد، البرشاء 1، دبي', null, array['تنظيف بالساعة', 'تنظيف عميق', 'تنظيف عند الانتقال والخروج', 'خادمة بدوام جزئي', 'خدمة مربيات']::text[], 'فريق العمل من الفلبينيات الموظفات لدى الوكالة.', true
where not exists (select 1 from public.service_providers where category = 'cleaning' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Maid Corner'));
