select 'domestic', 'TADBEER Domestic Workers (Housekeeping Domestic Workers Services LLC)', 'TADBEER Domestic Workers (Housekeeping Domestic Workers Services LLC)', 'دبي', 'أم الشيف', '+97147060100', 'https://www.tadbeer.me', null, 'مركز خدمات عمالة منزلية في أم الشيف بدبي يوفر عاملات ومربيات وسائقين ومقدمي رعاية.', 'https://www.tadbeer.me/', 'تذكر الشركة أن مراكزها لخدمات العمالة المنزلية مرخّصة من وزارة الموارد البشرية والتوطين. توفر باقات عمالة مقيمة تشمل العاملات والمربيات والسائقين ومقدمي الرعاية، إلى جانب خدمات التأشيرة والتجديد.', null, 'contact@tadbeer.me', 'مركز خدمات العمالة المنزلية، معرض رقم 4، مبنى إنديغو سكاي، شارع الشيخ زايد، أم الشيف، دبي', 'https://www.google.com/maps/place/TADBEER-+Housekeeping+Co./@25.126649,55.206082,12z/data=!4m5!3m4!1s0x0:0xac81b145355097ed!8m2!3d25.1266492!4d55.2060816?hl=en-US', array['تأشيرات العمالة المنزلية للكفلاء المواطنين والمقيمين', 'باقات عمالة مقيمة: عاملات ومربيات وسائقون', 'استقدام مباشر من الفلبين وإثيوبيا وميانمار وكينيا', 'مقدمو رعاية للأمومة والمواليد وكبار السن', 'خدمات تنظيف ورعاية أطفال عند الطلب']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'domestic' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('TADBEER Domestic Workers (Housekeeping Domestic Workers Services LLC)'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'domestic', 'Vicekeeper Domestic Workers Services L.L.C (Vicekeeper Tadbeer)', 'Vicekeeper Domestic Workers Services L.L.C (Vicekeeper Tadbeer)', 'دبي', 'برشا هايتس', '+97145497311', 'https://thetadbeer.ae', null, 'مركز خدمات عمالة منزلية في برشا هايتس بدبي يوفر مدبرات منزل ومربيات وخدمات تأشيرة.', 'https://thetadbeer.ae/', 'تذكر الشركة أنها مركز خدمات عمالة منزلية مرخّص من وزارة الموارد البشرية والتوطين ودائرة الاقتصاد والسياحة بدبي، برقم ترخيص وساطة وتشغيل مؤقت MB285826788AE ورخصة تجارية 1530615. توظف مدبرات منزل ومربيات ومقدمات رعاية وتتولى التأشيرة والعقود والرواتب.', 'https://thetadbeer.ae/assets/images/logo.png?v=2', 'admin@thetadbeer.ae', 'برج آي رايز، شارع حصة، برشا هايتس، دبي', 'https://www.google.com/maps?q=25.098372,55.176627', array['مدبرات منزل ومربيات مقيمات بباقة شهرية', 'باقات تأشيرة عاملة لمدة سنتين', 'التأشيرة والهوية والفحص الطبي والتأمين الصحي', 'رواتب نظام حماية الأجور ومستحقات نهاية الخدمة', 'تدريب العاملات ونقلهن إلى منزل العميل']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'domestic' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Vicekeeper Domestic Workers Services L.L.C (Vicekeeper Tadbeer)'));
