select 'domestic', 'maids.cc (Maids CC Domestic Workers Services)', 'maids.cc (Maids CC Domestic Workers Services)', 'دبي', null, null, 'https://www.maids.cc', null, 'شركة خدمات عاملات منزليات وتأشيرات في الإمارات توفر عاملات بدوام كامل وجزئي ومربيات.', 'https://www.maids.cc/', 'تذكر الشركة أنها مرخّصة من وزارة الموارد البشرية والتوطين برقم ترخيص 730266، وأنها كانت تُعرف سابقاً باسم تدبير حتى ديسمبر 2024. تقدم عاملات بدوام كامل وجزئي ومربيات وخدمات تأشيرة العاملة، وتشير إلى 25 فرعاً.', 'https://maids.cc/assets/images/logos/blue/logo-big.jpg?_v=17', null, null, 'https://www.google.com/maps/place/Maids.cc/@25.106767,55.225441,12z/data=!4m5!3m4!1s0x0:0x455109234a040a63!8m2!3d25.1067672!4d55.2254409?hl=en', array['عاملات بدوام كامل مقيمات وغير مقيمات', 'عاملات تنظيف بدوام جزئي', 'مربيات أطفال', 'تأشيرة العاملة المنزلية داخل الدولة وخارجها', 'جلسات تدريب منزلية للعاملات']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'domestic' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('maids.cc (Maids CC Domestic Workers Services)'));
