select 'domestic', 'Al Nukhba Center for Employment Services LLC (Tadbeer Housemaids)', 'Al Nukhba Center for Employment Services LLC (Tadbeer Housemaids)', 'أبوظبي', null, '+97126669888', 'https://alnukhbaservice.com', null, 'مركز في أبوظبي يقدم باقات تدبير لتوفير العاملات المنزليات والمربيات وكفالة العمالة المنزلية.', 'https://alnukhbaservice.com/tad-beer/', 'يذكر المركز أن خدماته مرخّصة بالكامل من وزارة الموارد البشرية والتوطين. يقدم تحت علامة Tadbeer Housemaids باقات مؤقتة وتقليدية ومرنة للعاملات المنزليات، إضافة إلى كفالة السائقين والمربيات والطهاة وخدمات معاملات حكومية.', 'https://alnukhbaservice.com/wp-content/uploads/2024/05/1.png', null, null, null, array['باقة مؤقتة لعاملات متاحات على مدار الساعة', 'باقة تقليدية للاستقدام من الخارج بضمان سنتين', 'باقة مرنة لعاملات بدوام جزئي', 'كفالة سائقين ومربيات وطهاة', 'خدمات توجيه وتسهيل والطباعة']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'domestic' and emirate = 'أبوظبي' and lower(coalesce(name_en, name_ar)) = lower('Al Nukhba Center for Employment Services LLC (Tadbeer Housemaids)'));
