select 'domestic', 'Al Nuamiya Domestic Workers Services Center (Tadbeer Al Nuamiya)', 'Al Nuamiya Domestic Workers Services Center (Tadbeer Al Nuamiya)', 'عجمان', 'النعيمية', '+97167488029', 'https://tadbeer-ajman.ae', null, 'مركز خدمات عمالة منزلية في النعيمية بعجمان يوفر عاملات بدوام كامل وجزئي وخدمات التأشيرة.', 'https://tadbeer-ajman.ae/', 'يصف المركز نفسه بأنه مركز تدبير معتمد من وزارة الموارد البشرية والتوطين في عجمان. يوفر عاملات منزليات بدوام كامل وجزئي بباقات شهرية وسنوية، ويقدم خدمات التأشيرة والإقامة.', 'https://tadbeer-ajman.ae/wp-content/uploads/2025/09/tadbeer-original-logo-png-e1757655970501.png', 'tadbeeralnuamiya2025@gmail.com', 'شارع الشيخ جابر الصباح، النعيمية 2، عجمان', 'https://www.google.com/maps/place/AL+NUAMIYA+DOMESTIC+WORKERS+SERVICES+CENTER+%D9%85%D8%B1%D9%83%D8%B2+%D8%A7%D9%84%D9%86%D8%B9%D9%8A%D9%85%D9%8A%D8%A9+%D9%84%D8%AE%D8%AF%D9%85%D8%A7%D8%AA+%D8%A7%D9%84%D8%B9%D9%85%D8%A7%D9%84%D8%A9+%D8%A7%D9%84%D9%85%D8%B3%D8%A7%D8%B9%D8%AF%D8%A9%E2%80%AD/@25.3869302,55.450477,17z/data=!3m1!4b1!4m6!3m5!1s0x3e5f59a2d5c96d27:0xc16a7858db48e9da!8m2!3d25.3869254!4d55.4530519!16s%2Fg%2F11h0t0j9jn', array['عاملات منزليات بدوام كامل وجزئي', 'تأشيرات العاملات وخدمات الإقامة', 'باقات شهرية وسنوية', 'جليسات أطفال وطاهيات وممرضات منزليات']::text[], null, true
