select 'garden', 'Desert Landscape Co. (L.L.C) - Desert Group', 'Desert Landscape Co. (L.L.C) - Desert Group', 'دبي', null, '+971 4 590 4000', 'https://www.desertgroup.ae', 1988, 'شركة تنسيق حدائق في دبي تأسست عام 1988 وتعمل في تصميم المساحات الخضراء وإنشائها وصيانتها.', 'https://www.bali.org.uk/members/desert-landscape-co-l-l-c-183646/', 'تأسست مجموعة ديزرت عام 1988 وبدأت في تنسيق الحدائق للمجمعات السكنية والفنادق والمشاريع الحكومية والملاعب. تضم المجموعة ثماني شركات تغطي التصميم والإنشاء والصيانة والمشاتل ومركز بيع الحدائق وأحواض السباحة وتنسيق المساحات الداخلية، ولها مكاتب في دول الخليج وتايلاند.', null, 'group@desertgroup.ae', 'دبي، ص.ب 37579', null, array['برج العرب', 'برج خليفة', 'أتلانتس النخلة', 'متحف المستقبل', 'ملاعب الجولف في جميرا جولف إستيتس']::text[], null, true
