select 'movers', 'GAC International Moving', 'GAC International Moving', 'دبي', 'Jebel Ali', '+971 800 668464', 'https://moving.gac.com', 1956, 'ذراع النقل الدولي لمجموعة GAC، مقرها في جبل علي بدبي، وتقدم نقل المنازل والتخزين وخدمات الوصول.', 'https://moving.gac.com/about', 'تأسست مجموعة GAC عام 1956 في الكويت، وبدأت عمليات النقل في دبي عام 1972، وأنشأت أول مركز توزيع في المنطقة بدبي عام 1993. تقدم خدمات النقل من وإلى الإمارات والتخليص الجمركي والتخزين قصير وطويل الأجل ونقل الفلل. ويذكر الموقع اعتمادات منها FIDI-FAIM وISO 9001 وISO 14001، ولها مكتب آخر في الكرامة بدبي.', 'https://moving.gac.com/hs-fs/hubfs/GAC_2019/Images/GAC_logo.png', 'moving.dubai@gac.com', 'جبل علي، البوابة 4، التقاطع 6، دبي', null, array['النقل الدولي من وإلى الإمارات', 'التخليص الجمركي والشحن', 'التخزين قصير وطويل الأجل', 'نقل الفلل داخل الإمارات', 'خدمات الوصول والاستقرار']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'movers' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('GAC International Moving'));
