select 'pets', 'Tail Waggin'' Pet Grooming', 'Tail Waggin'' Pet Grooming', 'دبي', 'Dubai Hills Estate', '+971503666622', 'https://www.tailwaggin.ae/', null, 'خدمة تجميل متنقلة للحيوانات الأليفة في دبي عبر أسطول من عربات السبا، ولها صالون في دبي هيلز.', 'https://www.tailwaggin.ae/mobilegrooming', 'تقدم تيل واغن تجميلاً متنقلاً للحيوانات الأليفة عند باب العميل باستخدام أسطول من عربات السبا. وتشمل الخدمة الاستحمام والتجفيف وتنظيف الأذنين وتقليم الأظافر، مع تصفيف الشعر في الباقة الكاملة.', 'https://static.wixstatic.com/media/7cd3ae_d425d8f3e7914ab999b9180f895883b9~mv2_d_2994_1546_s_2.png/v1/crop/x_378,y_11,w_2271,h_1312/fill/w_150,h_82,al_c,q_85,usm_0.66_1.00_0.01,enc_avif,quality_auto/cs.png', 'info@tailwaggin.ae', 'سواي ريزيدنسز، محل 2، قرب مستشفى كينغز كوليدج، دبي هيلز إستيت، دبي', null, array['تجميل متنقل بعربات السبا', 'التجميل الأساسي', 'التجميل الكامل مع التصفيف', 'صالون تيل واغن في دبي هيلز']::text[], 'يذكر الموقع أن جميع المزينين مدربون مهنياً ولديهم خبرة لا تقل عن 5 سنوات.', true
where not exists (select 1 from public.service_providers where category = 'pets' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Tail Waggin'' Pet Grooming'));
