select 'pets', 'Clever Dog', 'Clever Dog', 'دبي', 'Jebel Ali Industrial', '+971509887003', 'https://www.cleverdog.ae/', null, 'مركز في دبي لتدريب الكلاب وإيواء الحيوانات الأليفة ورعايتها نهارياً وتجميلها ونقلها.', 'https://www.cleverdog.ae/', 'تقدم كليفر دوغ في دبي تدريب الكلاب حضورياً وعن بُعد، وإيواء الحيوانات الأليفة والرعاية النهارية للقطط والكلاب، إضافة إلى التجميل ونقل الحيوانات. ويذكر الموقع أن المنشأة مزودة بأنظمة أمان وبروتوكولات للوقاية من الأمراض وتعمل سبعة أيام في الأسبوع.', null, null, 'جبل علي الصناعية الأولى، مستودع 26، دبي', null, array['تدريب الكلاب', 'إيواء الحيوانات الأليفة', 'رعاية نهارية للقطط والكلاب', 'تجميل الحيوانات', 'نقل الحيوانات الأليفة']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'pets' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Clever Dog'));
