select 'pools', 'Falcon Pools', 'Falcon Pools', 'دبي', 'القوز', '+971 4 340 6577', 'https://falconpool.com', null, 'شركة في دبي لتصميم وإنشاء المسابح وتجديدها وصيانتها السنوية.', 'https://falconpool.com/', 'تقدم فالكون بولز خدمات تصميم وإنشاء المسابح والجاكوزي والنوافير وتنسيق الحدائق. كما تقدم أعمال الترميم والتجديد والإصلاح وعقود الصيانة السنوية وتوريد ملحقات المسابح.', 'https://falconpool.com/wp-content/uploads/2024/07/Logo.png', 'info@falconpool.com', 'شارع المنارة، منطقة القوز الإبداعية، مستودع السرور، الطابق الأرضي، دبي', null, array['مسبح مع موقد نار في دبي هيلز', 'مسبح خارجي في الخوانيج', 'من العملاء المعلنين: وصل العقارية', 'من العملاء المعلنين: إمداد', 'من العملاء المعلنين: جميرا']::text[], null, true
