select 'pools', 'Pools R Us LLC', 'Pools R Us LLC', 'دبي', null, '+971 4 340 7887', 'https://www.poolsrusdubai.com', null, 'شركة في دبي لتصميم وإنشاء المسابح وصيانتها وتنظيفها وتنسيق المساحات الخارجية.', 'https://www.poolsrusdubai.com/', 'تقدم بولز آر أس تصميم وإنشاء المسابح بأنواعها (إنفينيتي، الفائض، السكيمر) وتنسيق المساحات الخارجية. وتشمل خدماتها صيانة المسابح وتنظيفها والفحوص المخبرية وأعمال الإصلاح والترميم وأسوار الأمان.', 'https://poolsrusdubai.com/images/logo.svg', null, 'ص.ب 50699، دبي', null, array['تصميم وإنشاء المسابح', 'صيانة وتنظيف المسابح', 'أسوار أمان المسابح (Magnifence)', 'الفحوص المخبرية وأعمال التصحيح', 'الترميم والتجديد والاستشارات']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'pools' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Pools R Us LLC'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'pools', 'Infinite Leisure Pools (ILP)', 'Infinite Leisure Pools (ILP)', 'دبي', 'أبو هيل', '+971 4 429 0044', 'https://ilpools.ae', 2013, 'شركة مقاولات مسابح في دبي تأسست عام 2013 تعمل في إنشاء المسابح وصيانتها وتنسيق الحدائق.', 'https://ilpools.ae/about/', 'تأسست إنفينيت ليجر عام 2013 وتعمل في إنشاء المسابح والحدائق وإصلاحها وتوريد منتجات المسابح. تشمل خدماتها كشف التسربات والعزل والتبليط وأنظمة التسخين والتبريد وإنشاء البحيرات والساونا وغرف البخار.', 'https://ilpools.ae/wp-content/uploads/2023/02/cropped-infinite-leisure-pool-company-dubai-1.png', 'info@ilpools.ae', 'مكتب 205، مركز سيتي باي للأعمال، شارع أبو هيل الأول، دبي', null, array['إعادة تبليط مسبح فندق أرماني - برج خليفة', 'ون آند أونلي رويال ميراج، دبي', 'كوف بيتش، أبوظبي', 'جميرا جولف إستيت', 'مشروع بحيرة صناعية في الخوانيج']::text[], 'يذكر الموقع ثلاثة مديرين عامّين: زاهد علي شاه وحسين حبيب وحامد علي شاه.', true
where not exists (select 1 from public.service_providers where category = 'pools' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Infinite Leisure Pools (ILP)'));
