select 'pools', 'Lushly Pools (Lushly Technical Works L.L.C.)', 'Lushly Pools (Lushly Technical Works L.L.C.)', 'دبي', 'موتور سيتي', '+971 58 550 3211', 'https://lushlypools.com', null, 'شركة تصميم وتنفيذ في دبي تعمل في إنشاء المسابح وتنسيق الحدائق وصيانة المسابح.', 'https://lushlypools.com/', 'لاشلي بولز علامة تملكها وتديرها شركة لاشلي للأعمال الفنية ذ.م.م في دبي. تقدم إنشاء المسابح الخرسانية ومسابح الإنفينيتي واللاب وتجديدها وصيانتها، إضافة إلى تنسيق الحدائق والمظلات والمطابخ الخارجية والتصميم الداخلي.', 'https://lushlypools.com/wp-content/uploads/2026/09/logo-lushly-pools-png-74x74.png', 'info@lushlypools.com', 'الطابق الثالث، برج المراقبة، موتور سيتي، دبي', null, array['إنشاء المسابح الخرسانية', 'مسابح الإنفينيتي واللاب', 'تجديد المسابح وصيانتها', 'تنسيق الحدائق والري', 'المطابخ الخارجية والمظلات']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'pools' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Lushly Pools (Lushly Technical Works L.L.C.)'));
