select 'pools', 'KABCO Group', 'KABCO Group', 'دبي', 'مجمع دبي للاستثمار', '+971 4 585 8293', 'https://www.kabcogroup.com', 2015, 'شركة في دبي تأسست عام 2015 لتصميم المسابح وإنشائها وصيانتها وتجديدها وتنسيق الحدائق.', 'https://www.kabcogroup.com/swimming-pools/', 'تأسست كابكو عام 2015 وتقدم تصميم المسابح وإنشاءها وصيانتها وتنظيفها وتجديدها، إلى جانب تنسيق الحدائق والتصميم والتشطيب الداخلي وتوسعة الفلل. ويذكر الموقع حصولها على موافقات للعمل في مجتمعات إعمار ونخيل وداماك وغيرها.', 'https://www.kabcogroup.com/wp-content/uploads/2025/08/kabco-logo.svg', 'info@kabcogroup.com', 'مكتب 116، مركز بيان، مجمع دبي للاستثمار 1، دبي', null, array['مشاريع في جميرا بارك', 'مشاريع في دبي هيلز إستيت', 'مشاريع في المروج (Meadows)', 'مشاريع في داماك هيلز', 'مشاريع في الفرجان']::text[], 'أسسها المهندسان محمد أسعد (هندسة ميكانيكية) ومحمد باقر (هندسة مدنية).', true
where not exists (select 1 from public.service_providers where category = 'pools' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('KABCO Group'));
