select 'pools', 'Atlanta Pools', 'Atlanta Pools', 'أبوظبي', 'مصفح', '+971 54 477 9984', 'https://atlantapools.ae', null, 'شركة في مصفح بأبوظبي لإنشاء المسابح وصيانتها وتنظيفها وتنسيق الحدائق.', 'https://atlantapools.ae/', 'تقدم أتلانتا بولز إنشاء المسابح وصيانتها وتنظيفها وعقود الصيانة السنوية في أبوظبي. كما تقدم صيانة الحدائق وتنسيقها وخدمات النوافير، ويذكر الموقع تنفيذها مشاريع لفلل ومنشآت تجارية وفندقية في أبوظبي.', 'https://atlantapools.ae/wp-content/uploads/al_opt_content/IMAGE/atlantapools.ae/wp-content/uploads/2025/08/Atlanta_Pools_Logo-1.webp.bv.webp', 'info@atlantapools.ae', 'مصفح M-9، أبوظبي', null, array['إنشاء المسابح', 'صيانة وتنظيف المسابح', 'عقود الصيانة السنوية', 'تنسيق وصيانة الحدائق', 'خدمات النوافير']::text[], null, true
