select 'property_mgmt', 'betterhomes LLC', 'betterhomes LLC', 'دبي', 'الخليج التجاري', '+971 4 408 1000', 'https://www.bhomes.com/', null, 'شركة عقارية في دبي تقدم إدارة العقارات السكنية والتجارية والمباني للملاك.', 'https://www.bhomes.com/en/property-management', 'تقدم betterhomes إدارة العقارات السكنية والتجارية في الإمارات، وتشمل التسويق والتأجير وفحص المستأجرين وتحصيل الإيجار وتنسيق الصيانة والتجديدات ضمن باقات فضية وذهبية وبلاتينية. وتعلن أنها تدير أكثر من 8,500 وحدة و65 مبنى بنسبة إشغال 96%.', 'https://d33om22pidobo4.cloudfront.net/storage/betterhomes-logopng-35921563-a1ec-40ce-a5ba-fed278f16e64.png', 'customercare@bhomes.com', 'فيجن تاور، الطابق 42، الخليج التجاري، دبي', null, array['إدارة أكثر من 8,500 وحدة و65 مبنى', 'إدارة المباني متعددة الوحدات', 'فحص المستأجرين وتحصيل الإيجار', 'فحوصات الاستلام والتسليم (Snagging)', 'باقات إدارة فضية وذهبية وبلاتينية']::text[], 'تذكر الشركة أن لديها أكثر من 300 متخصص.', true
where not exists (select 1 from public.service_providers where category = 'property_mgmt' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('betterhomes LLC'));
