select 'property_mgmt', 'Dacha Real Estate', 'Dacha Real Estate', 'دبي', 'دبي مارينا', '+971 4 423 2006', 'https://www.dacha.ae/', 2004, 'وكالة عقارية في دبي تأسست عام 2004 وتقدم باقات إدارة العقارات للملاك.', 'https://www.dacha.ae/about-dacha/our-story/', 'تقدم Dacha Real Estate باقات لإدارة جميع أنواع العقارات في دبي بفريق معتمد من RERA، تشمل الأعمال الإدارية وفحص التسليم والصيانة والإصلاحات وإدارة الإيجارات وتحصيلها. تأسست عام 2004 ولها مكاتب في مارينا بلازا بدبي مارينا ونخلة جميرا.', 'https://ggfx-dachare.s3.eu-west-2.amazonaws.com/i.prod/dacha_logo_a4c52644e6.png', 'info@dacha.ae', 'مكتب 2101 و2404، مارينا بلازا، دبي مارينا، دبي، صندوق بريد 171418', 'https://maps.app.goo.gl/r9aEyjMjM6fG2NMh8', array['إدارة الإيجارات وتحصيلها وحل النزاعات', 'الصيانة والإصلاحات على مدار الساعة', 'فحص التسليم للمشترين والمستأجرين', 'الأعمال الإدارية والتعامل مع الجهات الحكومية']::text[], 'أسستها أنجليكا شيغلوفا، ويضم فريقها أكثر من 70 مختصاً عقارياً معتمداً من RERA.', true
where not exists (select 1 from public.service_providers where category = 'property_mgmt' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Dacha Real Estate'));
