select 'security', 'NAFFCO', 'NAFFCO', 'دبي', 'المنطقة الحرة لجبل علي', '+971 4 815 1111', 'https://www.naffco.com', null, 'شركة مقرها جبل علي في دبي لتصنيع معدات مكافحة الحريق وأنظمة الحماية من الحريق وتوريدها.', 'https://www.naffco.com/naffcofactories/index.html', 'نافكو شركة مقرها الرئيسي في المنطقة الحرة لجبل علي بدبي، تصنّع معدات مكافحة الحريق ومضخات الحريق والأبواب المقاومة للحريق وأنظمة الإطفاء والتحكم في الدخان. كما تقدم خدمات الصيانة والتدريب وأنظمة التيار المنخفض والأنظمة الأمنية المتكاملة، ولديها عدة مصانع في جبل علي.', 'https://www.naffco.com/media/logo/stores/61/naffco_logo_for_websites.png', 'info@naffco.com', 'المقر العالمي، المنطقة الحرة لجبل علي، دبي، ص.ب 262169', 'https://maps.app.goo.gl/e1q1C3MHVGtypbaX9', array['معدات مكافحة الحريق (طفايات وخراطيم وصناديق)', 'مضخات الحريق ولوحات التحكم', 'الأبواب المقاومة للحريق', 'أنظمة الرش والإطفاء بالغاز والرغوة', 'سيارات الإطفاء والإسعاف']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'security' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('NAFFCO'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'smart_home', 'LEXA Lifestyle', 'LEXA Lifestyle', 'دبي', 'القوز 1', '+971 55 445 2224', 'https://lexalifestyle.com/', null, 'شركة أتمتة منازل فاخرة في دبي تقدم المنازل الذكية والإضاءة الذكية والسينما المنزلية.', 'https://lexalifestyle.com/contact', 'تقدم LEXA Lifestyle حلول المنزل الذكي والإضاءة الذكية والسينما المنزلية في دبي. ولديها مركز تجربة (Experience Centre) وأداة لتخطيط مشاريع الفلل والشقق والبنتهاوس والمشاريع التجارية.', 'https://files.ihgbrands.com/lexa/logos/22529024f00e_20260404051300.webp', 'info@lexalifestyle.com', 'القوز 1، شارع الشيخ زايد، التقاطع الثالث، دبي، الإمارات', 'https://maps.google.com/?q=Al+Quoz+1+Dubai', array['السينما المنزلية', 'الإضاءة الذكية', 'حلول المنزل الذكي', 'مركز تجربة في دبي']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'smart_home' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('LEXA Lifestyle'));
