select 'smart_home', 'Luxsmart Trading LLC (LUXSMART)', 'Luxsmart Trading LLC (LUXSMART)', 'دبي', null, '+971 55 651 0494', 'https://luxsmart.ae/', null, 'شركة أتمتة منازل في دبي تصمم حلولاً متكاملة للفلل والشقق الفاخرة واليخوت.', 'https://luxsmart.ae/', 'تصمم LuxSmart حلولاً متكاملة للفلل والشقق الفاخرة واليخوت في أنحاء الإمارات. وتشمل خدماتها أتمتة المنازل والسينما المنزلية والإضاءة (KNX وLutron وDynalite) والشبكات والأمن والصيانة.', 'https://luxsmart.ae/images/0/15301469/noBgColor-e1o2Q5FPFhPDagiQMa8C2Q.png', 'info@luxsmart.ae', 'صندوق بريد 22234، دبي، الإمارات', null, array['شقة خاصة في أتلانتس ذا رويال (KNX مع Savant)', 'سينما منزلية لفيلا في جميرا جولف إستيت', 'فيلا خاصة في نخلة جميرا (صوت وصورة متعدد الغرف وإضاءة Dynalite)', 'أتمتة اليخوت']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'smart_home' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Luxsmart Trading LLC (LUXSMART)'));
