select 'smart_home', 'Al Tasami Technologies LLC', 'Al Tasami Technologies LLC', 'الشارقة', 'البطينة', '+971 6 565 7587', 'https://altasami.com/', 2003, 'شركة في الشارقة لحلول تقنية المعلومات وأتمتة المنازل الذكية والأمن منذ 2003.', 'https://altasami.com/', 'تقدم Al Tasami Technologies حلول تقنية المعلومات وأتمتة المنازل الذكية والأمن في الشارقة وأنحاء الإمارات منذ 2003. وتشمل خدماتها الشبكات وأنظمة الهاتف وكاميرات المراقبة والتحكم بالدخول والصوت والصورة وإنترنت الأشياء.', 'https://altasami.com/logo.png', 'info@altasami.com', 'البطينة، الشارقة، الإمارات', null, array['أتمتة فيلا فاخرة (Lutron وControl4)', 'شبكة مقر شركة من 5 طوابق', 'نظام أمن لمركز لوجستي', 'كاميرات المراقبة والتحكم بالدخول']::text[], null, true
