select 'smart_home', 'The Switch Company', 'The Switch Company', 'العين', 'شارع الشيخ زايد، قرب مسجد الشيخة سلامة', '+971 56 539 9549', 'https://theswitchcompany.ae/', 2012, 'فرع العين لشركة متخصصة في حلول المنازل الذكية بنظام KNX والإضاءة والأمن.', 'https://theswitchcompany.ae/', 'شركة متخصصة في حلول المنازل الذكية بنظام KNX، تجمع بين منتجات عالية الجودة وأنظمة موثوقة وخبرة هندسية. تقدم التحكم الذكي في الإضاءة والتكييف والستائر والتحكم الصوتي، إضافة إلى الأمن والسينما المنزلية.', 'https://theswitchcompany.ae/wp-content/uploads/2024/11/footerLogo.svg', 'Info@theswitchcompany.ae', 'مكتب 101، مبنى العسالية، شارع السلامة، شارع الشيخ زايد، قرب مسجد الشيخة سلامة، العين', 'https://maps.google.com?q=The%20Switch%20Company%20-%20Al%20Ain,%20Sheikh%20-%20%D9%90Al%20Ain%20-%20Office%20101%20Zayed%20Bin%20Sultan%20St%20-%20next%20to%20Shikha%20Salama%20mosque%20-%20Abu%20Dhabi&ftid=0x3e8ab7bef46cbd53:0x72d72ad5fa4a74a', array['التحكم الذكي بنظام KNX (إضاءة، تكييف، ستائر، تحكم صوتي)', 'حلول الإضاءة المعمارية والخارجية والداخلية', 'أنظمة الأمن: كاميرات مراقبة وإنترفون وتحكم بالدخول', 'السينما المنزلية وأنظمة الصوت', 'التحكم الذكي بالإضاءة في برج الابتكار الشمسي لهيئة كهرباء ومياه دبي (DEWA)']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'smart_home' and emirate = 'العين' and lower(coalesce(name_en, name_ar)) = lower('The Switch Company'));

-- إعادة تفعيل حماية الإغراق
do $$ begin
  if exists (select 1 from pg_trigger where tgname = 'aq_rate_limit_service_providers') then
    alter table public.service_providers enable trigger aq_rate_limit_service_providers;
  end if;
end $$;

-- للتأكد: عدد الشركات في كل قسم وإمارة
select category, emirate, count(*) from public.service_providers where is_active group by 1, 2 order by 1, 3 desc;
